  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.updated", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      const project = await projectRepo.findProjectById(
        payload.orgId,
        payload.projectId,
      );
      if (project) await indexProject(payload.orgId, project);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.subjectId as Issue["id"],
      );
      if (issue) await indexIssue(payload.orgId, issue);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}

/**
 * Attachment metadata plus the storage quota guard.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { issueResource, requireFound } from "./_support";
import type {
  CreateAttachmentInput,
  DeleteAttachmentInput,
} from "@/schemas/attachment";
import type { IssueId, OrgId } from "@/types/common";
import type { IssueAttachment } from "@/types/issue";
import type { Actor } from "@/types/member";

const BYTES_PER_MB = 1024 * 1024;

export async function listAttachments(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueAttachment[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return attachmentRepo.listAttachments(orgId, issueId);
}

/**
 * Records an upload after checking the org still has storage left. The quota
 * is in megabytes and the upload is in bytes, so the incoming size is rounded
 * up to whole megabytes before the comparison — half a megabyte still costs
 * one against the plan.
 */
export async function addAttachment(
  actor: Actor,
  input: CreateAttachmentInput,
): Promise<IssueAttachment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usage = await usageRepo.getUsage(input.orgId);
  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);

  if (
    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
  ) {
    throw new Error(
      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
    );
  }

  const attachment = await attachmentRepo.insertAttachment(
    input,
    actor.userId,
  );
  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });

  return attachment;
}

/** Removing an attachment gives the megabytes back to the quota. */
export async function removeAttachment(
  actor: Actor,
  input: DeleteAttachmentInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);

  const attachment = requireFound(
    await findAttachment(input.orgId, input.attachmentId),
    "Attachment",
    input.attachmentId,
  );

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, attachment.issueId),
    "Issue",
    attachment.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
  await usageRepo.incrementUsage(input.orgId, {
    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
  });
}

/**
 * The attachment repository only reads by issue, because that is the only way
 * the UI ever reaches one. A delete arrives with just an id, so the org's
 * issues are walked until the row turns up.
 */
async function findAttachment(
  orgId: OrgId,
  attachmentId: string,
): Promise<IssueAttachment | null> {
  const page = await issueRepo.listIssues({
    orgId,
    limit: 100,
    cursor: null,
    includeArchived: true,
  });

  for (const issue of page.items) {
    const rows = await attachmentRepo.listAttachments(orgId, issue.id);
    const match = rows.find((row) => row.id === attachmentId);
    if (match) return match;
  }

  return null;
}
/**
 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

  const used = await webhookRepo.countEndpoints(input.orgId);
  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
  }

  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
}

export async function updateWebhook(
  actor: Actor,
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  return webhookRepo.updateEndpoint(input);
}

export async function deleteWebhook(
  actor: Actor,
  input: DeleteWebhookInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
}

/**
 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
/**
 * Membership and role changes, including the invariant that an organization always keeps one owner.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, memberResource, requireFound } from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Actor, Member, MemberWithUser, Role } from "@/types/member";

/** How many members are scanned when counting the remaining owners. */
const OWNER_SCAN_LIMIT = 100;

export async function listMembers(
  actor: Actor,
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:read", {
    kind: "organization",
    orgId: input.orgId,
  });
  return memberRepo.listMembers(input);
}

/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
 * it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

/**
 * Organization rows plus slug uniqueness lookups. Plans are resolved from
 * subscriptions on every read, falling back to the stored organization plan.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import { findSubscription } from "./subscription-repository";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { OrganizationRow } from "@/server/db";
import type { Organization } from "@/types/organization";

async function organizationWithPlan(row: OrganizationRow): Promise<Organization> {
  const organization = toOrganization(row);
  const subscription = await findSubscription(organization.id);
  return { ...organization, plan: subscription?.plan ?? organization.plan };
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? organizationWithPlan(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? organizationWithPlan(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return Promise.all(rows.map((row) => organizationWithPlan(row.org)));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return organizationWithPlan(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return organizationWithPlan(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return organizationWithPlan(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number; capacity: number };

const buckets = new Map<string, BucketState>();

/** Default plans for callers that do not pass a current plan explicitly. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(plan: PlanId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
  plan: PlanId = planByOrg.get(orgId) ?? "free",
): Promise<RateLimitVerdict> {
  const config = configFor(plan, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? {
    tokens: config.capacity,
    updatedAt: nowMs,
    capacity: config.capacity,
  };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  // Preserve tokens already spent when a plan changes the bucket's capacity.
  const tokens = Math.max(
    0,
    Math.min(
      config.capacity,
      state.tokens + config.capacity - state.capacity +
        elapsedMinutes * config.refillPerMinute,
    ),
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, {
    tokens: remaining,
    updatedAt: nowMs,
    capacity: config.capacity,
  });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
import {
  consumeRateLimit as consumeTokens,
  type RateLimitVerdict,
} from "@/lib/rate-limit";
import { findOrgById } from "@/server/repositories/organization-repository";
import type { OrgId } from "@/types/common";

/** Resolve the current subscription plan before every tenant burst check. */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const organization = await findOrgById(orgId);
  return consumeTokens(orgId, bucketKey, cost, organization?.plan ?? "free");
}

