/bin/zsh -lc "pnpm exec tsx --input-type=module <<'TS'
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { eq } from 'drizzle-orm';
import { getDb, subscriptions, organizations } from './src/server/db/index.ts';
import { runMigrations } from './src/server/db/migrate.ts';
import * as users from './src/server/repositories/user-repository.ts';
import * as orgs from './src/server/repositories/organization-repository.ts';
import * as subs from './src/server/repositories/subscription-repository.ts';
import * as billing from './src/server/services/billing-service.ts';
import * as organizationService from './src/server/services/organization-service.ts';
import { consumeRateLimit } from './src/server/services/rate-limit-service.ts';
import { resetRateLimits } from './src/lib/rate-limit.ts';
import { buildFlagContext } from './src/server/services/feature-flag-service.ts';
import { isEnabled } from './src/lib/feature-flags.ts';
import { runTrialExpiryJob } from './src/server/jobs/trial-expiry-job.ts';

const dir = mkdtempSync(join(tmpdir(), 'taskflow-plan-check-'));
process.env.TASKFLOW_DB_PATH = join(dir, 'check.db');
try {
  await runMigrations();
  const owner = await users.insertUser({ email: 'owner@plan-check.test', name: 'Owner', passwordHash: 'unused' });
  const workspace = await organizationService.createOrganization(owner.id, { name: 'Check', slug: 'check', plan: 'free' });
  const actor = { userId: owner.id, orgId: workspace.id, role: 'owner' };
  for (let i = 0; i < 60; i++) assert.equal((await consumeRateLimit(workspace.id, 'comment:create')).allowed, true);
  assert.equal((await consumeRateLimit(workspace.id, 'comment:create')).allowed, false);
  await billing.changePlan(actor, { orgId: workspace.id, plan: 'growth', interval: 'monthly' });
  assert.equal(getDb().select().from(organizations).where(eq(organizations.id, workspace.id)).get().plan, 'free');
  assert.equal((await orgs.findOrgById(workspace.id)).plan, 'growth');
  assert.equal((await orgs.findOrgBySlug(workspace.slug)).plan, 'growth');
  assert.equal((await orgs.listOrgsForUser(owner.id))[0].plan, 'growth');
  assert.equal((await consumeRateLimit(workspace.id, 'comment:create')).allowed, true);
  assert.equal(isEnabled('webhooks', buildFlagContext(actor, await orgs.findOrgById(workspace.id))), true);
  await billing.changePlan(actor, { orgId: workspace.id, plan: 'starter', interval: 'monthly' });
  assert.equal(isEnabled('webhooks', buildFlagContext(actor, await orgs.findOrgById(workspace.id))), false);

  const trial = await organizationService.createOrganization(owner.id, { name: 'Trial', slug: 'trial-check', plan: 'growth' });
  const legacy = await orgs.insertOrg({ name: 'Legacy', slug: 'legacy-check', plan: 'starter' }, owner.id);
  assert.equal((await orgs.findOrgById(legacy.id)).plan, 'starter');
  const sweepTime = new Date(Date.now() + 15 * 24 * 60 * 60 * 1000);
  assert.equal((await runTrialExpiryJob(sweepTime)).processed, 1);
  assert.equal((await subs.findSubscription(workspace.id)).plan, 'starter');
  assert.equal((await orgs.findOrgById(trial.id)).plan, 'free');
  assert.equal((await subs.findSubscription(trial.id)).status, 'active');
  assert.equal((await runTrialExpiryJob(sweepTime)).processed, 0);
  assert.equal((await orgs.updateOrg(trial.id, { orgId: trial.id, name: 'Expired Trial' })).plan, 'free');
  getDb().delete(subscriptions).where(eq(subscriptions.orgId, trial.id)).run();
  assert.equal((await orgs.findOrgById(trial.id)).plan, 'growth');
  resetRateLimits();
  console.log('Subscription authority, fallback, burst resizing, and trial expiry checks passed.');
} finally {
  getDb()."'$client.close();
  rmSync(dir, { recursive: true, force: true });
}
TS'

